    a['p_WaterBaseOpacity'] = bpy.props.FloatProperty(name='基础不透明度', description='水的基础不透明度:水不看深度、不看菲涅尔时的透明程度,越大越不透明。\n_WaterBaseOpacity', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WaterBaseOpacity'))
