    a['p_WaterOpacityMinimum'] = bpy.props.FloatProperty(name='最小不透明度', description='水的最小不透明度:不管多浅、多正面,水至少有这么不透明。\n_WaterOpacityMinimum', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WaterOpacityMinimum'))
