    a['p_WaterStrokeOpacity'] = bpy.props.FloatProperty(name='描边不透明度', description='液面描边的不透明度:0 = 没有描边。\n_WaterStrokeOpacity', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_WaterStrokeOpacity'))
