    a['p_ParallaxIgnorePostExposure'] = bpy.props.BoolProperty(name='Parallax Ignore Post Exposure', description='视差发光不受自动曝光影响:打开后这一层发光的亮度不随画面曝光变化。\n_ParallaxIgnorePostExposure', default=True, update=kit.writer(stack, '_ParallaxIgnorePostExposure'))
    a['p_BaseColorTintCover'] = bpy.props.FloatProperty(name='Base Color Tint Cover', description='染色覆盖:0 = 基础颜色贴图乘染色(正常),1 = 完全用染色颜色盖掉贴图;用来把整个物体直接刷成一种纯色。\n_BaseColorTintCover', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_BaseColorTintCover'))
    a['p_BaseColorBrighterScale'] = bpy.props.FloatProperty(name='Base Color Brighter', description='基础颜色提亮倍率(1 – 2):大于 1 把固有色整体提亮,结果会被限制在最大亮度内。\n_BaseColorBrighterScale', default=1.0, min=1.0, max=2.0, update=kit.writer(stack, '_BaseColorBrighterScale'))
    a['p_RoughnessMin'] = bpy.props.FloatProperty(name='Roughness Min', description='粗糙度范围的下限:贴图里的粗糙度从黑到白会被重新映射到「Roughness Min」到「Roughness Max」之间;调高下限让最光滑处也不要太亮。\n_RoughnessMin', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_RoughnessMin'))
    a['p_RoughnessMax'] = bpy.props.FloatProperty(name='Roughness Max', description='粗糙度范围的上限:想让最粗糙处别太粗,就把它调小。\n_RoughnessMax', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_RoughnessMax'))
