    a['p_ThinFilmIntensity'] = bpy.props.FloatProperty(name='Thin Film Intensity', description='薄膜干涉的强度倍率(0 – 2):和「Thin Film Weight」相乘决定彩虹光泽有多明显。\n_ThinFilmIntensity', default=1.0, min=0.0, max=2.0, update=kit.writer(stack, '_ThinFilmIntensity'))
    a['p_LayerBlendMaskType'] = bpy.props.FloatProperty(name='Mask Source (0=MaskR else=NROA)', description='第二层的覆盖量从哪里来:0 = 用「Layer Blend Mask」图的 R 通道;1 = 第二层法线图的 A;2 = 基础颜色图的 A;3 = 法线图的 A;4 = 全部覆盖。\n_LayerBlendMaskType', default=0.0, update=kit.writer(stack, '_LayerBlendMaskType'))
