    a['p_LayerBlendUVType'] = bpy.props.FloatProperty(name='Layer UV (0=UV0 1=WorldXZ 2=UV2)', description='第二层材质贴图的 UV 来源:0 = 第一套 UV,1 = 世界坐标的 XZ(像铺在地面上的贴图,不随模型 UV),2 = 第三套 UV(UV2)。\n_LayerBlendUVType', default=0.0, update=kit.writer(stack, '_LayerBlendUVType'))
    a['p_TopBlendThreshold'] = bpy.props.FloatProperty(name='Top Blend Threshold', description='朝上覆盖的阈值(「朝上」模式用):法线朝上的程度超过它的地方才被第二层盖住;调小盖得越多(几乎所有朝上和斜面),调大只盖最平的顶面。\n_TopBlendThreshold', default=0.5, min=-1.0, max=1.0, update=kit.writer(stack, '_TopBlendThreshold'))
