    a['p_Layer1BaseNormalIntensity'] = bpy.props.FloatProperty(name='Layer1 Base Normal Intensity', description='第二层是否保留底下基础层的法线细节:0 = 第二层盖住的地方只显示自己的法线,1 = 把基础层的凹凸也叠上去。\n_Layer1BaseNormalIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_Layer1BaseNormalIntensity'))
