    a['p_Layer1Metallic'] = bpy.props.FloatProperty(name='Layer1 Metallic', description='第二层的金属度:0 非金属,1 金属;只在金属度来源选滑条时有用。\n_Layer1Metallic', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_Layer1Metallic'))
