    a['p_Layer1Saturation'] = bpy.props.FloatProperty(name='Layer1 Saturation', description='第二层的饱和度调整(−1 到 0):0 = 不变,越接近 −1 越灰;让积雪、灰尘更素。\n_Layer1Saturation', default=0.0, min=-1.0, max=0.0, update=kit.writer(stack, '_Layer1Saturation'))
