    a['p_LayerBlendHeight'] = bpy.props.BoolProperty(name='Layer Height Blend', description='按高度混合:打开后两层交界按高度图决定,凸起的地方先露出来(像积雪只盖在凹处、岩石棱角露出);关闭则按遮罩或朝向直接线性混合。\n_LayerBlendHeight', default=True, update=kit.writer(stack, '_LayerBlendHeight'))
