    a['p_ParallaxColorDark'] = bpy.props.FloatVectorProperty(name='Parallax Color Dark', description='视差图案暗处的发光颜色(HDR):图案从暗到亮在「Parallax Color Dark」和「Parallax Color」之间过渡。\n_ParallaxColorDark', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(0.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_ParallaxColorDark'))
    a['p_ExposureWithMiscParams'] = bpy.props.FloatVectorProperty(name='ExposureWithMiscParams (.y=后曝光)', description='引擎全局曝光参数,由场景自动写入,一般不用手调。\nX: 没有用到。\nY: 后曝光倍率:「不受自动曝光影响」的发光会乘它。\nZ: 没有用到。\nW: 没有用到。\n_ExposureWithMiscParams', size=4, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_ExposureWithMiscParams'))
    a['p_IgnorePostExposure'] = bpy.props.BoolProperty(name='不受自动曝光影响', description='自发光不受自动曝光影响:打开后发光亮度不随画面曝光变化(发光看起来永远一样亮)。\n_IgnorePostExposure', default=True, update=kit.writer(stack, '_IgnorePostExposure'))
    a['p_VFXParams1'] = bpy.props.FloatVectorProperty(name='VFX Grade (rgb = tint, w = saturation)', description='引擎全局的最终调色参数,由场景自动写入,一般不用手调。\nX: 整体染色的红分量(1 = 不变)。\nY: 整体染色的绿分量(1 = 不变)。\nZ: 整体染色的蓝分量(1 = 不变)。\nW: 整体饱和度:1 = 不变,0 = 灰度。\n_VFXParams1', size=4, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_VFXParams1'))
    a['p_SubsurfaceColor'] = bpy.props.FloatVectorProperty(name='Subsurface Color', description='次表面的颜色:透出来的光是什么颜色(蜡烛偏黄、肉偏红);再按「SSS Mode」决定是否乘上固有色。\n_SubsurfaceColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_SubsurfaceColor'))
    a['p_ThinFilmWeight'] = bpy.props.FloatProperty(name='Thin Film Weight', description='薄膜干涉的权重(0 – 1):0 = 没有彩虹光泽,1 = 完全使用薄膜算出的反射色。\n_ThinFilmWeight', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_ThinFilmWeight'))
    a['p_ThinFilmThickness'] = bpy.props.FloatProperty(name='Thin Film Thickness (um)', description='薄膜的厚度(微米):厚度不同干涉出的颜色不同,在 0 – 2 之间慢慢拖,颜色会循环变化。\n_ThinFilmThickness', default=0.5, min=0.0, max=2.0, update=kit.writer(stack, '_ThinFilmThickness'))
    a['p_ThinFilmIOR'] = bpy.props.FloatProperty(name='Thin Film IOR', description='薄膜的折射率:越大反射越强、彩色越明显,常见的油膜、水膜在 1.3 – 1.5。\n_ThinFilmIOR', default=1.4, min=1.0, max=3.0, update=kit.writer(stack, '_ThinFilmIOR'))
    a['p_PorosityFactorX'] = bpy.props.FloatProperty(name='Porosity Factor X (x Roughness)', description='孔隙度对粗糙度的影响(−1 – 1):越大,越粗糙的表面越「吸水」(高光越弱);决定淋雨时哪里更容易湿亮。\n_PorosityFactorX', default=0.2, min=-1.0, max=1.0, update=kit.writer(stack, '_PorosityFactorX'))
    a['p_PorosityFactorY'] = bpy.props.FloatProperty(name='Porosity Factor Y', description='孔隙度的基础值(0 – 1):不看粗糙度和金属度时表面本身的吸水程度,越大越吸水。\n_PorosityFactorY', default=0.4, min=0.0, max=1.0, update=kit.writer(stack, '_PorosityFactorY'))
    a['p_PorosityFactorZ'] = bpy.props.FloatProperty(name='Porosity Factor Z (x Metallic)', description='孔隙度对金属度的影响(−1 – 0):金属越强越不吸水,绝对值越大这个效果越明显。\n_PorosityFactorZ', default=0.0, min=-1.0, max=0.0, update=kit.writer(stack, '_PorosityFactorZ'))
    a['p_DisableVerticalFlow'] = bpy.props.BoolProperty(name='Disable Vertical Flow', description='关掉雨水沿竖直面流下的痕迹:打开后墙面等竖直面不再出现流水高光。\n_DisableVerticalFlow', default=False, update=kit.writer(stack, '_DisableVerticalFlow'))
    a['p_Reflectance'] = bpy.props.FloatProperty(name='Reflectance', description='植被的反射率(0 – 1):会被量化成 8 档,决定叶面反光的强弱;越大叶子越亮、越有蜡质感,调到 0.5 附近是通常的叶片。\n_Reflectance', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_Reflectance'))
    a['p_DiffuseUseVertexNormal'] = bpy.props.FloatProperty(name='Diffuse Use Vertex Normal', description='漫反射用模型法线的程度:0 = 用法线图修正过的法线算受光,1 = 完全用模型原始法线(整簇叶子受光更平滑统一)。\n_DiffuseUseVertexNormal', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_DiffuseUseVertexNormal'))
    a['p_BendNormalUpward'] = bpy.props.FloatProperty(name='Bend Normal Upward', description='草叶法线向上弯:0 = 保持法线图原样,1 = 所有草叶的法线都完全朝上(整片草地受光均匀、像一块毯子),草叶越像一团越调大。\n_BendNormalUpward', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_BendNormalUpward'))
    a['p_Transmission'] = bpy.props.FloatProperty(name='Transmission', description='透光强度:光线穿过叶片或草叶透出来的亮度,逆光看叶子发亮发绿就是它;越大越亮。\n_Transmission', default=0.2, min=0.0, max=1.0, update=kit.writer(stack, '_Transmission'))
    a['p_TransmissionDistanceFade'] = bpy.props.BoolProperty(name='Transmission Distance Fade', description='透光随距离淡出:打开后离镜头 50 – 60 米以外的叶子不再计算透光,省性能也避免远处叶子发白。\n_TransmissionDistanceFade', default=False, update=kit.writer(stack, '_TransmissionDistanceFade'))
    a['p_SubsurfaceIntensity'] = bpy.props.FloatProperty(name='Subsurface Intensity (Foliage)', description='次表面强度:叶片内部散射出来的柔和亮度,越大叶片受光处越通透柔和。\n_SubsurfaceIntensity', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_SubsurfaceIntensity'))
    a['p_backfaceGiIntensity'] = bpy.props.FloatProperty(name='Backface GI Intensity', description='背面的间接光强度:叶片背面受到的环境间接光的比例,越大背面越亮。\n_backfaceGiIntensity', default=0.2, min=0.0, max=1.0, update=kit.writer(stack, '_backfaceGiIntensity'))
    a['p_FrontfaceIndirectDiffuse'] = bpy.props.FloatProperty(name='Frontface Indirect Diffuse', description='阔叶正面的间接漫反射(阔叶透光模式用):朝上的叶面接收的环境光比例。\n_FrontfaceIndirectDiffuse', default=0.2, min=0.0, max=1.0, update=kit.writer(stack, '_FrontfaceIndirectDiffuse'))
    a['p_BackfaceIndirectDiffuse'] = bpy.props.FloatProperty(name='Backface Indirect Diffuse', description='阔叶背面的间接漫反射(阔叶透光模式用):朝下的叶面接收的环境光比例,会再乘透光遮罩。\n_BackfaceIndirectDiffuse', default=0.2, min=0.0, max=1.0, update=kit.writer(stack, '_BackfaceIndirectDiffuse'))
    a['p_AoAffectTransmissionStart'] = bpy.props.FloatProperty(name='AO To Transmission Start', description='遮蔽对透光的起点:遮蔽值低于它的深处(树冠里面)完全没有透光;调大让更多暗处不透光。\n_AoAffectTransmissionStart', default=0.0, min=0.0, max=0.99, update=kit.writer(stack, '_AoAffectTransmissionStart'))
    a['p_AoAffectTransmissionRange'] = bpy.props.FloatProperty(name='AO To Transmission Range', description='遮蔽对透光的过渡宽度:从「没有透光」过渡到「完整透光」所跨的遮蔽范围,越小越硬。\n_AoAffectTransmissionRange', default=0.01, min=0.01, max=0.9, update=kit.writer(stack, '_AoAffectTransmissionRange'))
    a['p_AoAffectSubsurfaceStart'] = bpy.props.FloatProperty(name='AO To Subsurface Start', description='遮蔽对次表面的起点:遮蔽值低于它的深处没有次表面。\n_AoAffectSubsurfaceStart', default=0.0, min=0.0, max=0.99, update=kit.writer(stack, '_AoAffectSubsurfaceStart'))
    a['p_AoAffectSubsurfaceRange'] = bpy.props.FloatProperty(name='AO To Subsurface Range', description='遮蔽对次表面的过渡宽度:越小过渡越硬。\n_AoAffectSubsurfaceRange', default=0.01, min=0.01, max=0.9, update=kit.writer(stack, '_AoAffectSubsurfaceRange'))
    a['p_FakeDirectionalShadowStrength'] = bpy.props.FloatProperty(name='Fake Directional Shadow Strength', description='假方向光阴影的强度:按叶子朝向和光方向的夹角直接压暗背光的叶子,不用真的阴影也能做出树冠里明暗层次;0 = 没有。\n_FakeDirectionalShadowStrength', default=0.0, min=0.0, max=2.0, update=kit.writer(stack, '_FakeDirectionalShadowStrength'))
    a['p_FakeDirectionalShadowPow'] = bpy.props.FloatProperty(name='Fake Directional Shadow Pow', description='假阴影的指数:越大暗部越集中在完全背光的叶子上,越小压暗越大面积。\n_FakeDirectionalShadowPow', default=1.0, min=0.01, max=5.0, update=kit.writer(stack, '_FakeDirectionalShadowPow'))
    a['p_OcclusionShadow'] = bpy.props.FloatProperty(name='Occlusion Affects Shadow', description='遮蔽对阴影的影响:0 = 阴影不看顶点遮蔽,1 = 顶点遮蔽(树冠内部)会一并压暗阴影。\n_OcclusionShadow', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_OcclusionShadow'))
    a['p_VerticalNormalThreshold'] = bpy.props.FloatProperty(name='Vertical Normal Threshold', description='朝下的叶子加深遮蔽的阈值:法线朝上的程度低于它(朝下、朝侧面)的叶子会被加深遮蔽。\n_VerticalNormalThreshold', default=0.0, min=-1.0, max=1.0, update=kit.writer(stack, '_VerticalNormalThreshold'))
    a['p_VerticalNormalBoostAO'] = bpy.props.FloatProperty(name='Vertical Normal Boost AO', description='朝下的叶子遮蔽加深的强度:越大朝下的叶子越暗。\n_VerticalNormalBoostAO', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_VerticalNormalBoostAO'))
    a['p_VerticalNormalAffectShadow'] = bpy.props.FloatProperty(name='Vertical Normal Affect Shadow', description='朝下的叶子对阴影的影响:越大朝下的叶子受光的阴影越重。\n_VerticalNormalAffectShadow', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_VerticalNormalAffectShadow'))
    a['p_CanopyRampStartAtTop'] = bpy.props.BoolProperty(name='Canopy Ramp Start At Top', description='树冠渐变从树冠顶部算起:关闭时从底部算起,打开则反过来(顶部渐变范围)。\n_CanopyRampStartAtTop', default=False, update=kit.writer(stack, '_CanopyRampStartAtTop'))
    a['p_CanopyRampColor'] = bpy.props.FloatVectorProperty(name='Canopy Ramp Color', description='树冠渐变的颜色:树冠高度(顶点色 A)落在「范围」内的叶子向这个颜色过渡,比如树冠顶部偏黄、底部偏深绿。\n_CanopyRampColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_CanopyRampColor'))
    a['p_CanopyRampColorBrighterScale'] = bpy.props.FloatProperty(name='Canopy Ramp Brighter', description='树冠渐变色的提亮倍率(1 – 3):大于 1 把渐变后的叶色提亮。\n_CanopyRampColorBrighterScale', default=1.0, min=1.0, max=3.0, update=kit.writer(stack, '_CanopyRampColorBrighterScale'))
    a['p_CanopyRampIntensity'] = bpy.props.FloatProperty(name='Canopy Ramp Intensity', description='树冠渐变的强度:0 = 没有渐变,1 = 完整渐变;还会乘透光遮罩(法线图 A 取反)。\n_CanopyRampIntensity', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_CanopyRampIntensity'))
    a['p_CanopyRampRange'] = bpy.props.FloatProperty(name='Canopy Ramp Range', description='树冠渐变的范围:树冠高度(顶点色 A)低于它的叶子被染色,越大染的越多。\n_CanopyRampRange', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_CanopyRampRange'))
    a['p_CanopyRampTransitionRange'] = bpy.props.FloatProperty(name='Canopy Ramp Transition', description='树冠渐变的过渡宽度:越大渐变边界越柔和。\n_CanopyRampTransitionRange', default=0.01, min=0.01, max=1.0, update=kit.writer(stack, '_CanopyRampTransitionRange'))
    a['p_CanopyRampColorCover'] = bpy.props.FloatProperty(name='Canopy Ramp Cover', description='树冠渐变色的覆盖度:0 = 渐变色乘在叶子原色上(保留叶子纹理),1 = 直接用渐变色盖掉叶色。\n_CanopyRampColorCover', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_CanopyRampColorCover'))
    a['p_FlipAoMask'] = bpy.props.FloatProperty(name='Flip AO Mask', description='翻转遮蔽遮罩:打开(1)后「AO 调色」用顶点色 R 的反相(原本暗的地方变成亮,亮的变暗)。\n_FlipAoMask', default=0.0, update=kit.writer(stack, '_FlipAoMask'))
    a['p_AoMaskTuneColor'] = bpy.props.FloatVectorProperty(name='AO Tune Color', description='遮蔽调色的颜色:按顶点色 R 画的遮蔽范围,让叶子在遮蔽程度不同的地方向这个颜色过渡(比如树冠内部偏暗绿)。\n_AoMaskTuneColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_AoMaskTuneColor'))
    a['p_AoMaskTuneColorBrighterScale'] = bpy.props.FloatProperty(name='AO Tune Brighter', description='遮蔽调色的提亮倍率(1 – 3):大于 1 把调色后的叶色提亮。\n_AoMaskTuneColorBrighterScale', default=1.0, min=1.0, max=3.0, update=kit.writer(stack, '_AoMaskTuneColorBrighterScale'))
    a['p_AoMaskTuneColorIntensity'] = bpy.props.FloatProperty(name='AO Tune Intensity', description='遮蔽调色的整体强度:0 = 不调色,1 = 完整使用;还会乘透光遮罩。\n_AoMaskTuneColorIntensity', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_AoMaskTuneColorIntensity'))
    a['p_AoMaskTuneColorRampStart'] = bpy.props.FloatProperty(name='AO Tune Ramp Start', description='遮蔽调色的起点:顶点色 R 超过它才开始调色。\n_AoMaskTuneColorRampStart', default=0.0, min=0.0, max=0.99, update=kit.writer(stack, '_AoMaskTuneColorRampStart'))
    a['p_AoMaskTuneColorRampRange'] = bpy.props.FloatProperty(name='AO Tune Ramp Range', description='遮蔽调色的过渡宽度:从起点到完全调色所跨的范围,越小越硬。\n_AoMaskTuneColorRampRange', default=0.2, min=0.01, max=0.9, update=kit.writer(stack, '_AoMaskTuneColorRampRange'))
    a['p_AoMaskTuneColorCover'] = bpy.props.FloatProperty(name='AO Tune Cover', description='遮蔽调色的覆盖度:0 = 调色乘在叶子原色上,1 = 直接用调色盖掉叶色。\n_AoMaskTuneColorCover', default=0.0, min=0.0, max=1.0, update=kit.writer(stack, '_AoMaskTuneColorCover'))
    a['p_BlendColor'] = bpy.props.FloatVectorProperty(name='Blend Color', description='叶片混色:叶子朝上的部分(受光多的顶面)向这个颜色混合,比如叶面朝上的地方偏亮黄,和背面拉开颜色。\nA: 混色的范围:越大(乘透光遮罩后)混色影响的叶子越多。\n_BlendColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_BlendColor'))
    a['p_BlendNormalAdd'] = bpy.props.FloatProperty(name='Blend Normal Add', description='混色朝向偏移:正值让更多朝向(斜的叶面)也算「朝上」被混色,负值只让最平的朝上叶面混色。\n_BlendNormalAdd', default=0.0, min=-1.0, max=1.0, update=kit.writer(stack, '_BlendNormalAdd'))
    a['p_BlendNormalPower'] = bpy.props.FloatProperty(name='Blend Normal Power', description='混色朝向的指数:越大混色越集中在完全朝上的叶面,边缘过渡越陡。\n_BlendNormalPower', default=1.0, min=0.3, max=15.0, update=kit.writer(stack, '_BlendNormalPower'))
    a['p_BlendWithVertexNormal'] = bpy.props.BoolProperty(name='Blend With Vertex Normal', description='混色按模型原始法线判断朝向:打开后不受法线图影响,整簇叶子的混色更统一。\n_BlendWithVertexNormal', default=False, update=kit.writer(stack, '_BlendWithVertexNormal'))
    a['p_DirParams'] = bpy.props.FloatVectorProperty(name='Dir Params', description='草的受光渐变(从草根到草尖):距离草根越远越亮、越透光。四个数控制这条渐变。\nX: 起点距离:离草根(物体原点)不到这个距离的部分保持最小值。\nY: 斜率:过了起点后亮度恢复到 1 的快慢,越大越快。\nZ: 最小值:草根处的亮度(0 – 1)。\nW: 枢轴下沉:把草根的位置往下挪这么多,让整根草的渐变整体后移。\n_DirParams', size=4, default=(0.1, 1.0, 0.8, 99.0,), update=kit.writer(stack, '_DirParams'))
    a['p_MaskOnDiffuse'] = bpy.props.FloatProperty(name='Mask On Diffuse', description='遮罩对漫反射的影响:0 = 草的漫反射只看根到尖的渐变,1 = 再乘上法线图 A 通道画的遮罩。\n_MaskOnDiffuse', default=1.0, min=0.01, max=1.0, update=kit.writer(stack, '_MaskOnDiffuse'))
    a['p_MaskOnTransmission'] = bpy.props.FloatProperty(name='Mask On Transmission', description='遮罩对透光的影响:0 = 草的透光只看根到尖的渐变,1 = 再乘上法线图 A 通道画的遮罩。\n_MaskOnTransmission', default=1.0, min=0.01, max=1.0, update=kit.writer(stack, '_MaskOnTransmission'))
    a['p_AoParams'] = bpy.props.FloatVectorProperty(name='Foliage AO Params', description='草的遮蔽渐变(从草根到草尖):草根暗、草尖亮的遮蔽,不依赖贴图。四个数含义和「Dir Params」一样。\nX: 起点距离:离草根不到这个距离的部分保持最小遮蔽。\nY: 斜率:过了起点后遮蔽恢复到没有遮蔽的快慢,越大越快。\nZ: 最小值:草根处的亮度(0 = 最暗)。\nW: 枢轴下沉:把草根的位置往下挪这么多。\n_AoParams', size=4, default=(0.1, 1.0, 0.8, 99.0,), update=kit.writer(stack, '_AoParams'))
    a['p_TrunkVertexAoStrength'] = bpy.props.FloatProperty(name='Trunk Vertex AO Strength', description='树干的顶点 AO 强度:模型顶点色 R 通道里画的遮蔽乘进树干的遮蔽,0 = 忽略顶点色,1 = 完全使用,树干根部、枝杈缝里画深一点就更有层次。\n_TrunkVertexAoStrength', default=1.0, min=0.0, max=1.0, update=kit.writer(stack, '_TrunkVertexAoStrength'))
    a['p_EnableTrunkRamp'] = bpy.props.BoolProperty(name='Trunk Ramp Enable', description='树干渐变色开关:按模型顶点色 A 通道(高度)给树干的某一段染上渐变色,比如树根发湿发苔。\n_EnableTrunkRamp', default=False, update=kit.writer(stack, '_EnableTrunkRamp'))
    a['p_TrunkRampColor'] = bpy.props.FloatVectorProperty(name='Trunk Ramp Color', description='树干渐变的颜色:顶点色 A 低于「范围」的那一段会向这个颜色过渡。\n_TrunkRampColor', size=4, subtype='COLOR_GAMMA', min=0.0, max=1.0, default=(1.0, 1.0, 1.0, 1.0,), update=kit.writer(stack, '_TrunkRampColor'))
