    a['p_EmissiveColorR'] = bpy.props.FloatVectorProperty(name='Emissive Color R', description='植被发光的颜色(HDR):发光图 R 通道(或基础颜色 A 通道)为白的地方发这个颜色。\n_EmissiveColorR', size=4, subtype='COLOR', min=0.0, soft_max=1.0, default=(0.0, 0.0, 0.0, 1.0,), update=kit.writer(stack, '_EmissiveColorR'))
