    a['p_WaterCausticMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='水波纹贴图', description='水波纹(焦散)图:水底闪动的光纹图案,亮度乘「水波纹强度」后加到浅水颜色上。\n_WaterCausticMap', update=kit.image_writer(stack, '_WaterCausticMap'))
