    a['p_IceOpacityMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='冰块不透明度贴图', description='冰块不透明度图:只读 R 通道,和「冰块不透明度阈值」比较,图里值比阈值大的地方冰块变成完全不透明(白色的冰),其它地方保持透明。\nR: 冰块不透明范围:越亮越先变成不透明。\n_IceOpacityMap', update=kit.image_writer(stack, '_IceOpacityMap'))
    a['p_FakeVolumeMask'] = bpy.props.PointerProperty(type=bpy.types.Image, name='伪体积蒙版', description='伪体积蒙版(非颜色数据):用 R 通道当「里面」这一层的高度图,白 = 靠近表面,黑 = 深处;裂缝、折射的位置与视差都由它决定。\nR: 里面这一层的高度:越亮越靠近表面。\n_FakeVolumeMask', update=kit.image_writer(stack, '_FakeVolumeMask'))
