    a['p_EmissiveMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Emissive Map', description='自发光贴图:R 通道决定哪里发「Emissive Color」的光,黑色处不发光。\nR: 发光范围:白 = 完全发光,黑 = 不发光。\nG: 预留给额外的发光颜色层,面板里没有对应颜色,一般不用。\nB: 同 G。\nA: 同 G。\n_EmissiveMap', update=kit.image_writer(stack, '_EmissiveMap'))
