    a['o_EmissiveMap'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), description='贴图偏移:图案在 UV 上整体平移多少,单位是 UV(1 = 平移一整张图)。\n_EmissiveMap_ST.zw', update=kit.st_writer(stack, '_EmissiveMap'))
