    a['p_DetailMap'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Detail Map (RG=N B=Rough A)', description='细节贴图(非颜色数据):R、G 是细节法线,B 是细节粗糙度,A 是遮蔽或遮罩。\nR: 细节法线的横向分量。\nG: 细节法线的纵向分量。\nB: 细节粗糙度:按「Detail PBR Intensity」混入基础粗糙度。\nA: 细节遮蔽(R+AO 模式下压暗缝隙);或者当作「只在这里加细节」的遮罩(遮罩模式选 DetailA 时)。\n_DetailMap', update=kit.image_writer(stack, '_DetailMap'))
