    a['p_MaskAlbedoGTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='遮罩G通道贴图', description='G 区域用的独立颜色贴图:替代「Mask G Color」那个纯色,用图案铺满这块区域。\nA: 粗糙度:在「G 通道粗糙下限」和「上限」之间插值。\n_MaskAlbedoGTex', update=kit.image_writer(stack, '_MaskAlbedoGTex'))
    a['p_MaskAlbedoBTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='遮罩B通道贴图', description='B 区域用的独立颜色贴图:替代「Mask B Color」那个纯色。\nA: 粗糙度:在「B 通道粗糙下限」和「上限」之间插值。\n_MaskAlbedoBTex', update=kit.image_writer(stack, '_MaskAlbedoBTex'))
    a['p_MaskAlbedoGNormalTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='遮罩G通道法线', description='G 区域用的独立法线图:覆盖这块区域的法线。\n_MaskAlbedoGNormalTex', update=kit.image_writer(stack, '_MaskAlbedoGNormalTex'))
    a['p_SubsurfaceNormalCurvatureTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='预积分3S曲率表', description='预积分次表面查找表:横轴是受光量(左边背光、右边正对光),纵轴是表面曲率;读出的颜色就是该处的次表面明暗。\n_SubsurfaceNormalCurvatureTex', update=kit.image_writer(stack, '_SubsurfaceNormalCurvatureTex'))
    a['p_TerrainDepthBuffer'] = bpy.props.PointerProperty(type=bpy.types.Image, name='地形深度图', description='地形深度图:引擎自动提供,Blender 里没有地形数据,这张图不起作用。\n_TerrainDepthBuffer', update=kit.image_writer(stack, '_TerrainDepthBuffer'))
    a['p_DissolveTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Dissolve Tex', description='溶解噪声图:只读 R 通道,亮的地方先保留、暗的地方先消失。\nR: 溶解的先后:越暗越先消失。\n_DissolveTex', update=kit.image_writer(stack, '_DissolveTex'))
    a['t_DissolveTex'] = bpy.props.FloatVectorProperty(name='平铺', size=2, default=(1.0, 1.0), description='贴图平铺:图案在 UV 上横向、纵向各重复几次,1 = 铺满一次,2 = 重复两次。\n_DissolveTex_ST.xy', update=kit.st_writer(stack, '_DissolveTex'))
    a['o_DissolveTex'] = bpy.props.FloatVectorProperty(name='偏移', size=2, default=(0.0, 0.0), description='贴图偏移:图案在 UV 上整体平移多少,单位是 UV(1 = 平移一整张图)。\n_DissolveTex_ST.zw', update=kit.st_writer(stack, '_DissolveTex'))
    a['p_DisturbTex'] = bpy.props.PointerProperty(type=bpy.types.Image, name='Disturb Tex', description='扰动图(非颜色数据):决定每个像素把图案往哪边推。\n_DisturbTex', update=kit.image_writer(stack, '_DisturbTex'))
