def draw_ContainerWater(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_RefractTex', '自定义折射贴图', 't_RefractTex', 'o_RefractTex')
        kit.texture(g0, p, 'p_WaterNormalMap', '水面法线贴图', 't_WaterNormalMap', 'o_WaterNormalMap')
        kit.texture(g0, p, 'p_WaterCausticMap', '水波纹贴图', 't_WaterCausticMap', 'o_WaterCausticMap')
        kit.texture(g0, p, 'p_DisplacementTex', '置换贴图', 't_DisplacementTex', 'o_DisplacementTex')
        kit.texture(g0, p, 'p_IceNormalMap', '冰块法线贴图', None, None)
        kit.texture(g0, p, 'p_IceOpacityMap', '冰块不透明度贴图', None, None)
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.texture(g0, p, 'p_BaseColorMap', 'Base Color Map', 't_BaseColorMap', 'o_BaseColorMap')
        kit.texture(g0, p, 'p_MatcapMap', 'Matcap Map', None, None)
        kit.texture(g0, p, 'p_ParallaxMap', 'Parallax Map', None, None)
        kit.texture(g0, p, 'p_NormalMap', 'Normal Map', 't_NormalMap', 'o_NormalMap')
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.prop(g0, p, 'p_RoughnessIntensity', 'Roughness Intensity')
        kit.prop(g0, p, 'p_MetallicIntensity', 'Metallic Intensity')
        kit.prop(g0, p, 'p_OcclusionIntensity', 'Occlusion Intensity')
        kit.prop(g0, p, 'p_SpecularIntensity', 'Specular Intensity')
        kit.prop(g0, p, 'p_UseCutoff', 'UseCutoff')
        kit.prop(g0, p, 'p_Cutoff', 'Alpha Cutoff')
        kit.prop(g0, p, 'p_UseDitherClip', 'UseDitherClip')
        kit.prop(g0, p, 'p_Use_VerexTexColorAsOpacity', '用顶点色控制Opacity')
        kit.prop(g0, p, 'p_Specular', 'Specular (Default 0.5)')
        kit.prop(g0, p, 'p_Roughness', '粗糙度')
        kit.prop(g0, p, 'p_MatCapIgnorePostExposure', 'Matcap 不受自动曝光影响')
        kit.prop(g0, p, 'p_RefractionIOR', '散射IOR')
        kit.prop(g0, p, 'p_RefractionColor', '折射颜色')
        kit.prop(g0, p, 'p_RefractionFresnelColor', '折射菲涅尔颜色')
        kit.prop(g0, p, 'p_RefractionStrength', '折射强度')
        kit.prop(g0, p, 'p_UseFresnel', 'Use Fresnel')
        kit.prop(g0, p, 'p_FresnelColor', '菲涅尔颜色')
        kit.prop(g0, p, 'p_FresnelBias', '菲涅尔偏移')
