def draw_Unlit(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.texture(g0, p, 'p_BaseColorMap', 'Base Color Map', 't_BaseColorMap', 'o_BaseColorMap')
        kit.texture(g0, p, 'p_NormalMap', 'Normal Map', 't_NormalMap', 'o_NormalMap')
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.prop(g0, p, 'p_RoughnessIntensity', 'Roughness Intensity')
        kit.prop(g0, p, 'p_MetallicIntensity', 'Metallic Intensity')
        kit.prop(g0, p, 'p_OcclusionIntensity', 'Occlusion Intensity')
        kit.prop(g0, p, 'p_SpecularIntensity', 'Specular Intensity')
        kit.prop(g0, p, 'p_UseCutoff', 'UseCutoff')
        kit.prop(g0, p, 'p_Cutoff', 'Alpha Cutoff')
        kit.prop(g0, p, 'p_UseDitherClip', 'UseDitherClip')
        kit.prop(g0, p, 'p_TwoSidedNormal', 'Two Sided Flip Backface Normal')
        kit.prop(g0, p, 'p_VoxelEmissionScale', 'Voxel Emission Scale')
        kit.prop(g0, p, 'p_AlphaClipThreshold', 'Alpha Clip Threshold')
        kit.prop(g0, p, 'p_CullMode', 'Cull Mode')

DRAW = {
    'ContainerWater': draw_ContainerWater,
    'Grass': draw_Grass,
    'Leaf': draw_Leaf,
    'Lit': draw_Lit,
    'LitEffect': draw_Lit,
    'LitEffectBlend': draw_Lit,
    'LitForward': draw_Lit,
    'LitHLod': draw_Lit,
    'LitTransparent': draw_Lit,
    'Trunk': draw_Lit,
    'Unlit': draw_Unlit,
}


def draw(kit, layout, material, p):
    function = DRAW.get(material.get('ruri_uber_part', ''))
    if function is None:
        kit.notice(layout, 'No panel layout for part ' + repr(material.get('ruri_uber_part', '')))
        return
    function(kit, layout, material, p)
